CREATE TABLE assessments (id text PRIMARY KEY, org_id text NOT NULL, branch_id text NOT NULL, class_id text NOT NULL, subject_id text NOT NULL, created_by text NOT NULL, title text NOT NULL, maximum numeric(8,2) NOT NULL CHECK(maximum>0), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','changes_requested','rejected','approved','published')), revision integer NOT NULL DEFAULT 1, published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,id), FOREIGN KEY(org_id,branch_id) REFERENCES branches(org_id,id), FOREIGN KEY(org_id,class_id) REFERENCES classes(org_id,id), FOREIGN KEY(org_id,subject_id) REFERENCES subjects(org_id,id), FOREIGN KEY(org_id,created_by) REFERENCES users(org_id,id));
CREATE TABLE mark_entries (org_id text NOT NULL, assessment_id text NOT NULL, student_id text NOT NULL, kind text NOT NULL CHECK(kind IN ('numeric','absent','exempt')), score numeric(8,2), CHECK((kind='numeric' AND score IS NOT NULL AND score>=0) OR (kind<>'numeric' AND score IS NULL)), PRIMARY KEY(org_id,assessment_id,student_id), FOREIGN KEY(org_id,assessment_id) REFERENCES assessments(org_id,id), FOREIGN KEY(org_id,student_id) REFERENCES students(org_id,id));
CREATE TABLE result_publications (id text PRIMARY KEY, org_id text NOT NULL, assessment_id text NOT NULL, revision integer NOT NULL, published_by text NOT NULL, published_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,assessment_id,revision), FOREIGN KEY(org_id,assessment_id) REFERENCES assessments(org_id,id), FOREIGN KEY(org_id,published_by) REFERENCES users(org_id,id));
CREATE TABLE announcements (id text PRIMARY KEY, org_id text NOT NULL, branch_id text NOT NULL, class_id text, created_by text NOT NULL, title text NOT NULL, body text NOT NULL, audience_roles jsonb NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','scheduled','published','archived')), scheduled_at timestamptz, published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,id), FOREIGN KEY(org_id,branch_id) REFERENCES branches(org_id,id), FOREIGN KEY(org_id,class_id) REFERENCES classes(org_id,id), FOREIGN KEY(org_id,created_by) REFERENCES users(org_id,id));
CREATE TABLE conversations (id text PRIMARY KEY, org_id text NOT NULL, branch_id text NOT NULL, student_id text NOT NULL, teacher_id text NOT NULL, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,id), UNIQUE(org_id,student_id,teacher_id), FOREIGN KEY(org_id,branch_id) REFERENCES branches(org_id,id), FOREIGN KEY(org_id,student_id) REFERENCES students(org_id,id), FOREIGN KEY(org_id,teacher_id) REFERENCES users(org_id,id), FOREIGN KEY(org_id,created_by) REFERENCES users(org_id,id));
CREATE TABLE conversation_messages (id text PRIMARY KEY, org_id text NOT NULL, conversation_id text NOT NULL, author_id text NOT NULL, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(org_id,conversation_id) REFERENCES conversations(org_id,id), FOREIGN KEY(org_id,author_id) REFERENCES users(org_id,id));
